Respond with a single JSON object conforming to this schema. Emit no prose, no explanation, and no markdown fences.

{
  "$defs": {
    "_Score": {
      "properties": {
        "id": {
          "title": "Id",
          "type": "string"
        },
        "score": {
          "title": "Score",
          "type": "number"
        },
        "rationale": {
          "title": "Rationale",
          "type": "string"
        }
      },
      "required": [
        "id",
        "score",
        "rationale"
      ],
      "title": "_Score",
      "type": "object"
    }
  },
  "properties": {
    "scores": {
      "items": {
        "$ref": "#/$defs/_Score"
      },
      "title": "Scores",
      "type": "array"
    }
  },
  "required": [
    "scores"
  ],
  "title": "_Scores",
  "type": "object"
}

